// Pure experimental library: no persistence, fetch, signing, or recipient admission.
import {canonical,digest,verifyReceipt} from './core.js';
import {importReport} from './file-problem.js';
import {importCorrection} from './correction-sidecar.js';
export const SCHEMA='reckoner.public-contribution-wal.experimental.v2';
export const HEADER=Object.freeze(['schema','record_id','sequence','operation','event_id','event_at','saved_at','source_ref','source_time','actor_attribution','reviewer_attribution','assistance_attribution','purpose','method','uncertainty','release_scope','artifact_manifest','target_selector','predecessor','genesis','row_digest','identity','admission']);
export const LIMITS=Object.freeze({rows:100,walBytes:2097152,fieldBytes:65536,rowBytes:262144,artifacts:200,artifactBytes:2097152,totalArtifactBytes:67108864,jsonDepth:8});

// Shared implementation keeps historical v2 bytes and hash rules unchanged.
export function createContributionWalContract({schema,header,extensionColumns=[]}){
 const SCHEMA=schema,HEADER=header;
const enc=new TextEncoder(),dec=new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}),need=(v,m)=>{if(!v)throw Error(m);},hash=v=>typeof v==='string'&&/^[a-f0-9]{64}$/.test(v),size=v=>enc.encode(v).length;
const exact=(o,ks)=>need(o&&typeof o==='object'&&!Array.isArray(o)&&Object.keys(o).sort().join('|')===[...ks].sort().join('|'),'Unexpected structured keys');
function text(v,max=4000,empty=false){need(typeof v==='string'&&(empty||v.length>0)&&size(v)<=max&&!/[\u0000\uD800-\uDFFF]/u.test(v),'Invalid text or text budget');}
function time(v,unknown=false){need(unknown&&v==='UNKNOWN'||typeof v==='string'&&/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z$/.test(v)&&Number.isFinite(Date.parse(v))&&new Date(v).toISOString()===v,'Invalid time');}
function decimal(v,zero=true){need(typeof v==='string'&&(zero?/^(0|[1-9][0-9]*)$/:/^[1-9][0-9]*$/).test(v)&&Number.isSafeInteger(Number(v)),'Invalid decimal');}
function walk(v,d=0){need(d<=LIMITS.jsonDepth,'JSON depth budget');if(v===null||typeof v==='boolean')return;if(typeof v==='string'){text(v,4000,true);return;}need(v&&typeof v==='object','JSON values must not be numeric');if(Array.isArray(v)){need(v.length<=200,'Array budget');for(const x of v)walk(x,d+1);}else for(const [k,x]of Object.entries(v)){need(/^[a-zA-Z][a-zA-Z0-9]*$/.test(k),'Non-ASCII structured key');walk(x,d+1);}}
function structured(raw){need(typeof raw==='string'&&size(raw)<=LIMITS.fieldBytes,'Field budget');const v=JSON.parse(raw);walk(v);need(canonical(v)===raw,'Noncanonical structured JSON');return v;}
const array=v=>need(Array.isArray(v),'Expected array');
function sourceRef(v){exact(v,['id','url','version','locator','sha256']);for(const k of ['id','version','locator'])text(v[k]);need(v.sha256==='UNKNOWN'||hash(v.sha256),'Invalid source pin');if(v.url!=='UNKNOWN'){text(v.url);const u=new URL(v.url);need(u.protocol==='https:'&&!u.username&&!u.password,'Invalid reference');}}
function shape(r){exact(r,HEADER);need(r.schema===SCHEMA&&r.operation==='creator_save'&&r.identity==='self_declared_unauthenticated'&&r.admission==='not_performed','Unsupported contract');for(const v of Object.values(r))text(v,LIMITS.fieldBytes);decimal(r.sequence);text(r.record_id,200);text(r.event_id,200);time(r.event_at,true);time(r.saved_at);need(hash(r.row_digest)&&(r.predecessor==='null'||hash(r.predecessor))&&(r.genesis==='null'||hash(r.genesis)),'Invalid chain pins');
 const sources=structured(r.source_ref);array(sources);sources.forEach(sourceRef);need(new Set(sources.map(x=>x.id)).size===sources.length,'Duplicate source reference');const times=structured(r.source_time);array(times);for(const t of times){exact(t,['sourceId','date']);need(sources.some(x=>x.id===t.sourceId),'Unknown source time');text(t.date);}need(times.length===sources.length&&new Set(times.map(x=>x.sourceId)).size===times.length,'Missing source time');
 const actor=structured(r.actor_attribution);exact(actor,['sourceActors','publisher','contributor','creator']);array(actor.sourceActors);actor.sourceActors.forEach(x=>text(x));for(const k of ['publisher','contributor','creator'])text(actor[k]);const reviewers=structured(r.reviewer_attribution);array(reviewers);for(const v of reviewers){exact(v,['label','role','artifactSha256','eventId']);text(v.label);need(['reviewer','mentor'].includes(v.role)&&hash(v.artifactSha256),'Invalid reviewer');text(v.eventId);}
 const assistance=structured(r.assistance_attribution);exact(assistance,['declaration','provider','model','runtime','persona','methodVersion']);need(['none-declared','AI-assisted','AI-scripted-example','UNKNOWN'].includes(assistance.declaration),'Invalid assistance');for(const k of ['provider','model','runtime','persona','methodVersion'])text(assistance[k]);
 const release=structured(r.release_scope);exact(release,['audience','declaration','artifactHashes']);need(['private_local_review','public_export'].includes(release.audience),'Invalid audience');need(release.declaration===(release.audience==='public_export'?'creator_asserts_exact_payload_release':'not_released'),'Invalid release declaration');array(release.artifactHashes);
 const manifest=structured(r.artifact_manifest);array(manifest);need(manifest.length>0&&manifest.length<=LIMITS.artifacts,'Manifest budget');let primary=0;const seen=new Set();for(const m of manifest){exact(m,['role','mediaType','schema','sha256','bytes','objectName','evidenceCompleteness']);need(['primary','supporting'].includes(m.role)&&m.mediaType==='application/json'&&hash(m.sha256),'Invalid manifest');primary+=m.role==='primary';decimal(m.bytes,false);need(Number(m.bytes)<=LIMITS.artifactBytes,'Artifact budget');need(m.objectName===m.sha256+'.json'&&!seen.has(m.sha256),'Artifact name or duplicate');seen.add(m.sha256);need(['source_bytes_not_carried','evidence_incomplete'].includes(m.evidenceCompleteness),'Unsupported completeness claim');text(m.schema);}need(primary===1,'Exactly one primary required');need(canonical(release.artifactHashes)===canonical([...seen].sort()),'Release hash scope mismatch');
 const selectors=structured(r.target_selector);array(selectors);for(const s of selectors){exact(s,['artifactSha256','pointer']);need(seen.has(s.artifactSha256)&&typeof s.pointer==='string'&&(s.pointer===''||s.pointer.startsWith('/')),'Invalid selector');}need(selectors.some(s=>s.artifactSha256===manifest.find(m=>m.role==='primary').sha256),'Primary selector missing');for(const v of reviewers)need(seen.has(v.artifactSha256),'Reviewer artifact missing');const extensions=[],typedReferences=[];for(const name of extensionColumns){const refs=structured(r[name]);array(refs);const unique=new Set();for(const ref of refs){exact(ref,['artifactSha256','pointer']);need(seen.has(ref.artifactSha256)&&typeof ref.pointer==='string','Invalid extension reference');const key=canonical(ref);need(!unique.has(key),'Duplicate extension reference');unique.add(key);const prefix=name==='bitnet_sidecars'?'modelRuns':'contextDefinitions';need(new RegExp('^/'+prefix+'/(0|[1-9][0-9]*)$').test(ref.pointer)&&manifest.some(m=>m.sha256===ref.artifactSha256&&m.schema==='garrison.cairn.receipt.v0.1'),'Extension must reference a typed carried receipt entry');extensions.push(ref);typedReferences.push({...ref,column:name});}}return {manifest,selectors:[...selectors,...extensions],reviewers,typedReferences};}
const quote=s=>'"'+s.replaceAll('"','""')+'"';
function encode(rows){return enc.encode([HEADER,...rows.map(r=>HEADER.map(k=>r[k]))].map(a=>a.map(quote).join(',')).join('\r\n')+'\r\n');}
function parse(bytes){need(bytes instanceof Uint8Array&&bytes.length<=LIMITS.walBytes,'WAL byte budget');const raw=dec.decode(bytes);need(!raw.startsWith('\uFEFF'),'BOM forbidden');let i=0,rows=[];while(i<raw.length){let row=[];while(true){need(raw[i++]==='"','Quoted CSV required');let v='',closed=false;while(i<raw.length){let c=raw[i++];if(c==='"'){if(raw[i]==='"'){v+='"';i++;}else{closed=true;break;}}else v+=c;}need(closed,'Unclosed field');row.push(v);need(row.length<=HEADER.length,'CSV width');if(raw[i]===','){i++;continue;}need(raw.slice(i,i+2)==='\r\n','CRLF required');i+=2;break;}need(row.length===HEADER.length,'CSV width');rows.push(row);need(rows.length<=LIMITS.rows+1,'Row budget');}need(rows.length>1&&canonical(rows.shift())===canonical(HEADER),'Exact header required');const out=rows.map(a=>Object.fromEntries(HEADER.map((k,j)=>[k,a[j]])));need(dec.decode(encode(out))===raw,'Noncanonical CSV');return out;}
async function rowHash(r){return digest(SCHEMA+'\n'+JSON.stringify(HEADER.filter(k=>k!=='row_digest').map(k=>r[k])));}
function resolve(root,p){if(p==='')return root;let v=root;for(const part of p.slice(1).split('/')){need(!/~(?![01])/u.test(part),'Invalid JSON pointer');const k=part.replaceAll('~1','/').replaceAll('~0','~');need(v!==null&&typeof v==='object'&&Object.hasOwn(v,k),'Unresolved selector');v=v[k];}return v;}
async function validateArtifacts(info,snapshots){const objects=new Map();for(const m of info.manifest){const b=snapshots.get(m.sha256);need(b&&b.length===Number(m.bytes)&&await digest(b)===m.sha256,'Missing, changed or wrong-size artifact');const raw=dec.decode(b);let obj;switch(m.schema){case 'file.problem-report.v1':obj=JSON.parse(raw);await importReport(raw);break;case 'ocr.correction-sidecar.v1':obj=JSON.parse(raw);await importCorrection(raw);break;case 'garrison.cairn.receipt.v0.1':obj=JSON.parse(raw);await verifyReceipt(obj);break;default:throw Error('Unsupported artifact schema');}need((obj.schema??obj.report?.schema??obj.proposal?.schema)===m.schema,'Artifact schema mismatch');objects.set(m.sha256,obj);}for(const s of info.selectors)resolve(objects.get(s.artifactSha256),s.pointer);for(const ref of info.typedReferences){const value=resolve(objects.get(ref.artifactSha256),ref.pointer);need(value&&typeof value==='object'&&!Array.isArray(value),'Extension entry must be an object');if(ref.column==='bitnet_sidecars')need(['id','provider','model','prompt','response'].every(k=>typeof value[k]==='string'),'Invalid model suggestion reference');else need(typeof value.id==='string'&&typeof value.version==='number'&&hash(value.sha256)&&typeof value.text==='string'&&Number.isSafeInteger(value.bytes),'Invalid review-context reference');}for(const v of info.reviewers){const o=objects.get(v.artifactSha256);need(o?.reviews?.some(x=>x.id===v.eventId&&x.reviewer===v.label&&(x.role??'reviewer')===v.role),'Reviewer attribution mismatch');}}
function own(map){need(map instanceof Map&&map.size<=LIMITS.artifacts,'Snapshot budget');const out=new Map();let n=0;for(const [k,b]of map){need(hash(k)&&b instanceof Uint8Array&&b.length>0&&b.length<=LIMITS.artifactBytes,'Snapshot shape');n+=b.length;need(n<=LIMITS.totalArtifactBytes,'Aggregate budget');out.set(k,new Uint8Array(b));}return out;}
async function verifyContributionWal(bytes,snapshots,{expectedGenesis=null,expectedTip=null}={}){need(expectedGenesis===null||hash(expectedGenesis),'Expected genesis');need(expectedTip===null||hash(expectedTip),'Expected tip');need(bytes instanceof Uint8Array&&bytes.length<=LIMITS.walBytes,'WAL byte budget');const rows=parse(new Uint8Array(bytes)),copies=own(snapshots);let genesis=null,previous=null;const ids=new Set(),used=new Set();for(let i=0;i<rows.length;i++){const r=rows[i];need(size(JSON.stringify(r))<=LIMITS.rowBytes,'Row budget');const info=shape(r);need(r.sequence===String(i)&&r.record_id===rows[0].record_id&&!ids.has(r.event_id),'Sequence, record or event conflict');ids.add(r.event_id);need(r.predecessor===(previous??'null')&&r.genesis===(genesis??'null'),'Broken chain');need(await rowHash(r)===r.row_digest,'Row digest mismatch');await validateArtifacts(info,copies);info.manifest.forEach(m=>used.add(m.sha256));genesis??=r.row_digest;previous=r.row_digest;}need(used.size===copies.size,'Unreferenced artifact');need(expectedGenesis===null||expectedGenesis===genesis,'Genesis checkpoint mismatch');need(expectedTip===null||expectedTip===previous,'Tip checkpoint mismatch: rollback or fork');return {schema:SCHEMA,rows,genesis,tip:previous,trust:expectedGenesis===null?'UNTRUSTED_SELF_CONSISTENT_HISTORY':'MATCHES_INDEPENDENT_GENESIS',freshness:expectedTip===null?'LATEST_VERSION_UNKNOWN':'MATCHES_INDEPENDENT_TIP',identity:'UNAUTHENTICATED',admission:'not_performed'};}
async function appendContributionWal({previousBytes=null,snapshots=new Map(),fields,expectedGenesis=null,expectedTip=null,audience='private_local_review'}){let rows=[],prior=null;const copies=own(snapshots);if(previousBytes!==null){need(hash(expectedGenesis)&&hash(expectedTip),'Independent genesis AND tip required');const oldRows=parse(previousBytes),used=new Set(oldRows.flatMap(r=>structured(r.artifact_manifest).map(m=>m.sha256)));const oldSnapshots=new Map([...copies].filter(([k])=>used.has(k)));prior=await verifyContributionWal(previousBytes,oldSnapshots,{expectedGenesis,expectedTip});rows=prior.rows;}else need(expectedGenesis===null&&expectedTip===null,'No checkpoints for new genesis');need(rows.length<LIMITS.rows,'Row budget');const r={...Object.fromEntries(extensionColumns.map(k=>[k,'[]'])),...fields,schema:SCHEMA,sequence:String(rows.length),operation:'creator_save',predecessor:prior?.tip??'null',genesis:prior?.genesis??'null',row_digest:'0'.repeat(64),identity:'self_declared_unauthenticated',admission:'not_performed'};const manifest=structured(r.artifact_manifest);r.release_scope=canonical({audience,declaration:audience==='public_export'?'creator_asserts_exact_payload_release':'not_released',artifactHashes:manifest.map(m=>m.sha256).sort()});r.row_digest=await rowHash(r);const bytes=encode([...rows,r]);const verification=await verifyContributionWal(bytes,copies,{expectedGenesis:prior?.genesis??null});return {bytes,snapshots:copies,verification};}
async function safeViewingProjection(bytes,snapshots,expected={}){const v=await verifyContributionWal(bytes,snapshots,expected);return {schema:'reckoner.contribution-wal-inert-view.experimental.v1',mediaType:'application/json',originalSha256:await digest(bytes),text:JSON.stringify({warning:'Render as inert text only; never evaluate cells or links',rows:v.rows},null,2)};}

 return {verifyContributionWal,appendContributionWal,safeViewingProjection};
}
const contract=createContributionWalContract({schema:SCHEMA,header:HEADER});
export const {verifyContributionWal,appendContributionWal,safeViewingProjection}=contract;
